using System.Collections.Generic; using System.ComponentModel.DataAnnotations; using OrderFlow.MVC.Models;
namespace OrderFlow.MVC.ViewModels { public class OrderCreateViewModel { [Required] public int CustomerId { get; set; } [Required, MinLength(1)] public IList<OrderItemInputViewModel> Items { get; set; } = new List<OrderItemInputViewModel>(); [Range(0, 1)] public decimal TaxRate { get; set; } = 0.08m; [StringLength(500)] public string ShippingAddress { get; set; } [StringLength(1000)] public string Notes { get; set; } } public class OrderItemInputViewModel { [Required] public int ProductId { get; set; } [Range(1, 99999)] public int Quantity { get; set; } } public class OrderStatusUpdateViewModel { [Required] public int OrderId { get; set; } [Required] public OrderStatus Status { get; set; } } public class OrderCalculationViewModel { public decimal Subtotal { get; set; } public decimal TaxAmount { get; set; } public decimal Total { get; set; } public IList<string> Errors { get; set; } = new List<string>(); } }
